const LALA_FOOD_STREETS_LCUOIBWG_OA_TRANSLATIONS = [
  `\u01a0, b\u00e2y gi\u1edd l\u1edbn t\u1eebng n\u00e0y r\u1ed3i m\u00e0 v\u1eabn kh\u00f4ng c\u00f3 nhi\u1ec1u ti\u1ec1n \u00e0?`,
  `\u00c0, c\u00e1i n\u00e0y kh\u00f4ng t\u00ecm \u0111\u01b0\u1ee3c \u0111\u00e2u.`,
  `Ch\u00e0o m\u1ecdi ng\u01b0\u1eddi, m\u00ecnh l\u00e0 Lala,`,
  `Ch\u00e0o m\u1eebng b\u1ea1n c\u00f9ng m\u00ecnh h\u1ecdc ti\u1ebfng Trung trong cu\u1ed9c s\u1ed1ng.`,
  `N\u1ebfu b\u1ea1n c\u1ea7n ph\u1ee5 \u0111\u1ec1 ti\u1ebfng Anh v\u00e0 b\u00ednh \u00e2m,`,
  `c\u00f3 th\u1ec3 nh\u1ea5n v\u00e0o ph\u00eda tr\u00ean m\u00e0n h\u00ecnh.`,
  `G\u1ea7n \u0111\u00e2y m\u00ecnh c\u00f9ng b\u1ed1 m\u1eb9 \u0111ang tr\u00fa \u0111\u00f4ng \u1edf B\u1eafc H\u1ea3i, Qu\u1ea3ng T\u00e2y,`,
  `H\u00f4m nay m\u00ecnh s\u1ebd c\u00f9ng m\u1eb9 \u0111i kh\u00e1m ph\u00e1 \u1ea9m th\u1ef1c B\u1eafc H\u1ea3i.`,
  `H\u00f4m nay m\u00ecnh s\u1ebd th\u1eed th\u00e1ch ch\u1ec9 d\u00f9ng ti\u1ec1n m\u1eb7t,`,
  `kh\u00f4ng d\u00f9ng \u0111i\u1ec7n tho\u1ea1i tr\u1ea3 ti\u1ec1n.`,
  `\u0110\u00e2y l\u00e0 t\u1ea5t c\u1ea3 ti\u1ec1n m\u1eb7t c\u1ee7a m\u00ecnh,`,
  `c\u00f3 th\u1ec3 b\u1ea1n bi\u1ebft h\u1ea7u h\u1ebft ng\u01b0\u1eddi Trung Qu\u1ed1c \u0111\u00e3 kh\u00f4ng d\u00f9ng ti\u1ec1n m\u1eb7t n\u1eefa r\u1ed3i.`,
  `T\u1ed5ng c\u1ed9ng 255 t\u1ec7.`,
  `M\u00ecnh v\u1eeba \u0111i \u0111\u01b0\u1ee3c 1 ph\u00fat,`,
  `th\u1eed th\u00e1ch \u0111\u1ea7u ti\u00ean \u0111\u00e3 \u0111\u1ebfn r\u1ed3i:`,
  `T\u00f4i kh\u00f4ng c\u00f3 ti\u1ec1n l\u1ebb \u0111i xe bu\u00fdt.`,
  `Hahaha. Th\u1ebf n\u00e0y nh\u00e9,`,
  `Xe bu\u00fdt gi\u00e1 2 t\u1ec7.`,
  `Hai t\u1ec7? \u0110\u00fang v\u1eady, 2 t\u1ec7 m\u1ed9t ng\u01b0\u1eddi.`,
  `Nh\u01b0ng t\u00f4i kh\u00f4ng c\u00f3 ti\u1ec1n l\u1ebb, t\u00f4i ch\u1ec9 c\u00f3 5 t\u1ec7.`,
  `Ng\u01b0\u1eddi Trung Qu\u1ed1c \u0111\u00e3 quen v\u1edbi vi\u1ec7c ch\u1ec9 d\u00f9ng \u0111i\u1ec7n tho\u1ea1i di \u0111\u1ed9ng \u0111\u1ec3 thanh to\u00e1n,`,
  `\u0110a s\u1ed1 m\u1ecdi ng\u01b0\u1eddi ra ngo\u00e0i kh\u00f4ng mang v\u00ed,`,
  `C\u0169ng kh\u00f4ng c\u00f3 ti\u1ec1n l\u1ebb.`,
  `V\u1eady n\u1ebfu b\u1ea1n kh\u00f4ng th\u1ec3 d\u00f9ng \u0111i\u1ec7n tho\u1ea1i di \u0111\u1ed9ng thanh to\u00e1n,`,
  `Ch\u1ec9 d\u00f9ng ti\u1ec1n m\u1eb7t, li\u1ec7u c\u00f3 g\u1eb7p nhi\u1ec1u kh\u00f3 kh\u0103n kh\u00f4ng?`,
  `H\u00e3y c\u00f9ng xem video c\u1ee7a t\u00f4i nh\u00e9.`,
  `\u0110\u00e2y l\u00e0 con ph\u1ed1 c\u1ed5 nh\u1ea5t \u1edf B\u1eafc H\u1ea3i.`,
  `M\u1ed9t s\u1ed1 ng\u00f4i nh\u00e0 tr\u00f4ng r\u1ea5t c\u0169 k\u1ef9,`,
  `Nh\u01b0ng c\u0169ng r\u1ea5t \u0111\u1eb7c tr\u01b0ng.`,
  `B\u1eafc H\u1ea3i l\u00e0 m\u1ed9t th\u00e0nh ph\u1ed1 nh\u1ecf ven bi\u1ec3n,`,
  `\u1ede \u0111\u00e2y c\u00f3 r\u1ea5t nhi\u1ec1u c\u1eeda h\u00e0ng b\u00e1n trang s\u1ee9c ng\u1ecdc trai.`,
  `C\u00e1i n\u00e0y 129 t\u1ec7,`,
  `H\u01a1i \u0111\u1eaft. B\u1ea1n th\u1ea5y n\u00f3 \u0111\u1eb9p kh\u00f4ng?`,
  `B\u00ecnh th\u01b0\u1eddng th\u00f4i. B\u00ecnh th\u01b0\u1eddng th\u00f4i.`,
  `C\u00e1i n\u00e0y c\u00f3 th\u1ec3 r\u1ebb h\u01a1n kh\u00f4ng?`,
  `Ch\u00fang t\u00f4i kh\u00f4ng gi\u1ea3m gi\u00e1, kh\u00f4ng m\u1eb7c c\u1ea3 \u0111\u00e2u c\u00f4.`,
  `\u1ed2, c\u00e1i n\u00e0y kh\u00f4ng m\u1eb7c c\u1ea3 \u0111\u01b0\u1ee3c \u00e0.`,
  `Nh\u01b0ng h\u00f4m nay m\u1ee5c ti\u00eau c\u1ee7a ch\u00fang ta kh\u00f4ng ph\u1ea3i l\u00e0 mua ng\u1ecdc trai,`,
  `M\u00e0 l\u00e0 kh\u00e1m ph\u00e1 \u1ea9m th\u1ef1c.`,
  `B\u1eafc H\u1ea3i r\u1ea5t g\u1ea7n Vi\u1ec7t Nam,`,
  `V\u00ec v\u1eady \u1edf \u0111\u00e2y c\u00f3 r\u1ea5t nhi\u1ec1u m\u00f3n \u0103n Vi\u1ec7t Nam.`,
  `V\u1eady 10 t\u1ec7 3 ly sao,`,
  `M\u1ed7i th\u1ee9 m\u1ed9t ly nh\u1ecf th\u00f4i \u00e0?`,
  `\u0110\u01b0\u1ee3c. Xem n\u00e0o. C\u00e1i n\u00e0y kh\u00f4ng c\u1ea7n b\u1ecf g\u00ec c\u1ea3.`,
  `C\u00e1i n\u00e0y kh\u00f4ng c\u1ea7n b\u1ecf g\u00ec c\u1ea3.`,
  `C\u00e1i n\u00e0y th\u00ec kh\u00f4ng d\u00f9ng \u0111\u1ed3 \u0103n k\u00e8m.`,
  `C\u00e1i n\u00e0y kh\u00f4ng d\u00f9ng \u0111\u1ed3 \u0103n k\u00e8m, c\u00e1i n\u00e0y l\u00e0 n\u1eeda c\u00e1i.`,
  `C\u00e1i n\u00e0y cay hay kh\u00f4ng cay?`,
  `Kh\u00f4ng cay. \u1eeam. To\u00e0n b\u1ed9 l\u00e0 kh\u00f4ng cay.`,
  `\u0110\u00fang v\u1eady. 10 t\u1ec7 3 c\u00e1i.`,
  `Ti\u1ec1n m\u1eb7t \u0111\u01b0\u1ee3c kh\u00f4ng?`,
  `\u0110\u01b0\u1ee3c. \u1eeam. N\u1ebfu 3 c\u00e1i th\u00ec c\u00f3 th\u1ec3 ch\u1ecdn 3 v\u1ecb kh\u00f4ng?`,
  `\u0110\u01b0\u1ee3c \u1ea1. \u1ed2, v\u1eady t\u00f4i mu\u1ed1n 3 v\u1ecb n\u00e0y.`,
  `\u0110\u01b0\u1ee3c. \u1eeam. N\u1ebfu c\u00f3 b\u1ea1n b\u00e8 Vi\u1ec7t Nam,`,
  `H\u00e3y cho t\u00f4i bi\u1ebft, m\u00f3n n\u00e0y tr\u00f4ng c\u00f3 gi\u1ed1ng m\u00f3n \u0103n v\u1eb7t \u0111\u00fang \u0111i\u1ec7u c\u1ee7a Vi\u1ec7t Nam kh\u00f4ng?`,
  `\u1eeam, c\u00e1i n\u00e0y th\u00ec d\u1ebbo d\u1ebbo,`,
  `\u1eeam, r\u1ed3i h\u01a1i chua chua m\u1ed9t ch\u00fat.`,
  `Chua chua, m\u1eb7n m\u1eb7n.`,
  `\u0110\u1ebfn Qu\u1ea3ng T\u00e2y du l\u1ecbch nh\u1ea5t \u0111\u1ecbnh ph\u1ea3i th\u1eed m\u00f3n \u0103n v\u1eb7t n\u00e0y,`,
  `G\u1ecdi l\u00e0 T\u1ee9n d\u00e3. \u1eeam, xin ch\u00e0o,`,
  `\u0110\u00e2y l\u00e0. \u0102n kem \u0111\u00f3.`,
  `C\u00f3 v\u1ecb g\u00ec?`,
  `C\u00f3 v\u1ecb chua, c\u00f3 v\u1ecb ng\u1ecdt.`,
  `Chua v\u00e0 ng\u1ecdt.`,
  `Cay c\u0169ng \u0111\u01b0\u1ee3c.`,
  `T\u00f4i l\u1ea5y m\u1ed9t \u00edt \u0111\u01b0\u1ee3c kh\u00f4ng?`,
  `\u0110\u01b0\u1ee3c ch\u1ee9, b\u1ea1n c\u1ee9 th\u00eam mu\u1ed1i v\u00e0o, t\u00f4i gi\u00fap b\u1ea1n th\u00eam c\u0169ng \u0111\u01b0\u1ee3c.`,
  `Nhi\u1ec1u ng\u01b0\u1eddi Trung Qu\u1ed1c kh\u00f4ng quen \u0103n lo\u1ea1i tr\u00e1i c\u00e2y n\u00e0y,`,
  `v\u00ec h\u1ecd c\u1ea3m th\u1ea5y th\u00eam mu\u1ed1i ho\u1eb7c \u1edbt b\u1ed9t v\u00e0o tr\u00e1i c\u00e2y th\u00ec h\u01a1i l\u1ea1.`,
  `C\u00e1c b\u1ea1n c\u00f3 th\u1ea5y l\u1ea1 kh\u00f4ng?`,
  `L\u1ea5y m\u1ed9t qu\u1ea3 d\u1ee9a kh\u00f4ng?`,
  `\u1eeam, kh\u1ebf, kh\u1ebf cho v\u00e0o \u0111\u01b0\u1ee3c kh\u00f4ng?`,
  `Kh\u1ebf c\u00f3 th\u1ec3 cho v\u00e0o c\u00f9ng kh\u00f4ng?`,
  `\u0110\u01b0\u1ee3c ch\u1ee9, \u0111\u01b0\u1ee3c ch\u1ee9.`,
  `L\u1ea5y d\u1ee9a kh\u00f4ng? D\u1ee9a kh\u00f4ng c\u1ea7n \u0111\u00e2u, l\u1ea5y m\u1ed9t ch\u00fat kh\u1ebf \u0111i.`,
  `\u0110\u1eebng. Cay qu\u00e1 t\u00f4i kh\u00f4ng mu\u1ed1n \u0111\u00e2u, kh\u00f4ng mu\u1ed1n \u0111\u00e2u.`,
  `\u01af\u0300m, th\u00eam m\u00f4\u0323t ca\u0301i n\u01b0\u0303a \u0111i.`,
  `Th\u00eam m\u00f4\u0323t ca\u0301i n\u01b0\u0303a. A.`,
  `\u0110\u01b0\u01a1\u0323c r\u00f4\u0300i, \u0111\u01b0\u01a1\u0323c r\u00f4\u0300i, th\u00ea\u0301 la\u0300 \u0111\u01b0\u01a1\u0323c r\u1ed3i.`,
  `Th\u1ebf th\u00ec c\u00e1i n\u00e0y t\u00f4i mu\u1ed1n chua m\u1ed9t ch\u00fat x\u00edu cay th\u00f4i.`,
  `C\u00e1i n\u00e0y? \u01a0, kh\u00f4ng ph\u1ea3i, t\u00f4i l\u00e0 t\u00f4i mu\u1ed1n c\u00e1i h\u01b0\u01a1ng v\u1ecb kia c\u01a1.`,
  `15 t\u1ec7. A, 15 t\u1ec7.`,
  `\u01af\u0300m. \u00d4\u0300, b\u00e2y gi\u1edd l\u1edbn v\u1eady m\u00e0 kh\u00f4ng c\u00f3 nhi\u1ec1u ti\u1ec1n \u0111\u1ebfn th\u1ebf \u00e0?`,
  `A, c\u00e1i n\u00e0y kh\u00f4ng th\u1ed1i l\u1ea1i \u0111\u01b0\u1ee3c \u0111\u00e2u.`,
  `\u01af\u0300m. V\u1eady t\u00f4i \u0111i mua m\u1ed9t th\u1ee9 kh\u00e1c \u0111\u1ed5i ti\u1ec1n l\u1ebb cho c\u00f4 \u0111\u01b0\u1ee3c kh\u00f4ng?`,
  `\u00d4ng ch\u1ee7, c\u00e1i kia c\u1ee7a \u00f4ng ba c\u00e2n kh\u00f4ng?`,
  `V\u1eady ph\u1ea3i tr\u1ea3 ti\u1ec1n \u0111\u1ea5y. C\u00e1i g\u00ec c\u01a1?`,
  `\u01af\u0300m, b\u1edfi v\u00ec t\u00f4i ch\u1ec9 c\u00f3 t\u1edd 10 t\u1ec7 v\u00e0 100 t\u1ec7 th\u00f4i.`,
  `Kh\u00f4ng c\u00f3 ti\u1ec1n l\u1ebb.`,
  `\u01af\u0300m. C\u00f3 sao \u0111\u00e2u?`,
  `Anh \u1ea5y \u0111ang t\u00ecm ng\u01b0\u1eddi \u0111\u1ed5i ti\u1ec1n gi\u00fap t\u00f4i.`,
  `Khi h\u1ecd n\u00f3i ti\u1ebfng \u0111\u1ecba ph\u01b0\u01a1ng, t\u00f4i ho\u00e0n to\u00e0n kh\u00f4ng hi\u1ec3u.`,
  `\u0110\u01b0\u1ee3c, c\u1ea3m \u01a1n, c\u1ea3m \u01a1n r\u1ea5t nhi\u1ec1u.`,
  `C\u00f3 th\u1ec3 c\u00e1c b\u1ea1n \u0111\u00e3 nh\u1eadn ra,`,
  `ng\u01b0\u1eddi \u1edf \u0111\u00e2y n\u00f3i ti\u1ebfng ph\u1ed5 th\u00f4ng kh\u00f4ng chu\u1ea9n,`,
  `gi\u1ecdng r\u1ea5t n\u1eb7ng. \u0110\u00f4i khi t\u00f4i c\u0169ng ch\u1ec9 hi\u1ec3u \u0111\u01b0\u1ee3c m\u1ed9t ph\u1ea7n,`,
  `r\u1ed3i d\u1ef1a v\u00e0o ng\u1eef c\u1ea3nh \u0111\u1ec3 \u0111o\u00e1n h\u1ecd n\u00f3i g\u00ec.`,
  `T\u00f4i c\u0169ng v\u1eady. 15 ph\u1ea3i kh\u00f4ng?`,
  `C\u1ea3m \u01a1n nh\u00e9. \u00c0, c\u1ea3m \u01a1n.`,
  `Kh\u00f4ng c\u00f3 ti\u1ec1n l\u1ebb v\u1eabn kh\u00e1 b\u1ea5t ti\u1ec7n,`,
  `hahaha, \u0111\u00fang v\u1eady. T\u00f4i v\u1ed1n d\u0129 \u0111\u00e3 \u0111i mua r\u1ed3i.`,
  `Kh\u00f4ng cay l\u1eafm. Kh\u00f4ng cay.`,
  `\u1eeam. C\u00f3 m\u1ed9t ch\u00fat.`,
  `\u1eeam. H\u01a1i m\u1eb7n \u00e0?`,
  `M\u1ed9t ch\u00fat. \u1eeam, h\u01a1i m\u1eb7n, h\u01a1i cay m\u1ed9t ch\u00fat.`,
  `R\u1ed3i c\u00f3 ch\u00fat chua v\u00e0 m\u1ed9t ch\u00fat ng\u1ecdt.`,
  `\u0110\u00fang v\u1eady, c\u00e1i n\u00e0y \u0111\u01b0\u1ee3c.`,
  `\u1eeam, \u0111\u00fang. N\u1ebfu b\u1ea1n kh\u00f4ng c\u00f3 \u0111\u1ee7 ti\u1ec1n l\u1ebb,`,
  `th\u00ec vi\u1ec7c mua \u0111\u1ed3 v\u1eabn kh\u00e1 b\u1ea5t ti\u1ec7n,`,
  `v\u00ec ng\u01b0\u1eddi b\u00e1n c\u0169ng kh\u00f4ng c\u00f3 ti\u1ec1n l\u1ebb \u0111\u1ec3 tr\u1ea3 l\u1ea1i b\u1ea1n.`,
  `N\u00ean khi t\u00f4i mua c\u00e0 ph\u00ea, t\u00f4i ch\u1ec9 c\u00f3 th\u1ec3 mua lo\u1ea1i c\u00f3 gi\u00e1 ti\u1ec1n ch\u1eb5n.`,
  `T\u00f4i tr\u1ea3 ti\u1ec1n m\u1eb7t \u0111\u01b0\u1ee3c kh\u00f4ng?`,
  `\u1eeam, kh\u00f4ng t\u00ecm th\u1ea5y ti\u1ec1n l\u1ebb,`,
  `kh\u00f4ng th\u1ec3. \u1ed2, c\u00f3 th\u1ec3 kh\u00f4ng th\u1ed1i l\u1ea1i \u0111\u01b0\u1ee3c.`,
  `N\u1ebfu b\u1ea1n c\u00f3 ti\u1ec1n l\u1ebb th\u00ec \u0111\u01b0\u1ee3c.`,
  `\u1eeam, v\u1eady \u0111\u1ec3 t\u00f4i xem,`,
  `t\u00f4i mu\u1ed1n, \u1eebm. T\u00f4i ch\u1ec9 c\u00f3 30,`,
  `40. Ly latte y\u1ebfn m\u1ea1ch n\u00e0y l\u00e0 30 ch\u1eb5n ph\u1ea3i kh\u00f4ng?`,
  `\u1eeam, caramel mu\u1ed1i bi\u1ec3n y\u1ebfn m\u1ea1ch l\u1ea1nh th\u00ec \u0111\u00fang.`,
  `Caramel mu\u1ed1i bi\u1ec3n y\u1ebfn m\u1ea1ch l\u1ea1nh.`,
  `\u0110\u00fang v\u1eady. Nh\u01b0ng t\u00f4i mu\u1ed1n m\u1ed9t ly c\u00e0 ph\u00ea n\u00f3ng.`,
  `\u1eeam, c\u00e1i \u0111\u00f3 c\u0169ng c\u00f3 th\u1ec3 l\u00e0m n\u00f3ng \u0111\u01b0\u1ee3c.`,
  `\u1ed2, c\u00e1i n\u00e0y l\u00e0m n\u00f3ng \u0111\u01b0\u1ee3c h\u1ea3?`,
  `C\u00f3 th\u1ec3 l\u00e0m n\u00f3ng \u0111\u01b0\u1ee3c.`,
  `\u1eeam. C\u00f4 y\u00ean t\u00e2m, c\u00e1i \u0111\u00f3 s\u1ebd kh\u00f4ng qu\u00e1 ng\u1ecdt \u0111\u00e2u.`,
  `\u0110\u01b0\u1ee3c th\u00f4i. T\u00f4i c\u0169ng c\u00f3 th\u1ec3 l\u00e0m gi\u1ea3m \u0111\u01b0\u1eddng cho c\u00f4.`,
  `\u00c0, \u0111\u01b0\u1ee3c \u0111\u01b0\u1ee3c, v\u1eady c\u00f4 l\u00e0m gi\u1ea3m \u0111\u01b0\u1eddng cho t\u00f4i nh\u00e9.`,
  `\u1eeam. T\u00f4i kh\u00f4ng th\u00edch \u0111\u1ed3 u\u1ed1ng qu\u00e1 ng\u1ecdt,`,
  `nh\u01b0ng ch\u1ec9 c\u00f3 lo\u1ea1i c\u00e0 ph\u00ea \u0111\u00f3 l\u00e0 gi\u00e1 ch\u1eb5n th\u00f4i,`,
  `n\u00ean n\u1ebfu c\u00f4 d\u00f9ng ti\u1ec1n m\u1eb7t th\u00ec nh\u1ea5t \u0111\u1ecbnh ph\u1ea3i chu\u1ea9n b\u1ecb th\u00eam ti\u1ec1n l\u1ebb.`,
  `Khi t\u00f4i \u0111i mua tr\u00e0 s\u1eefa c\u0169ng c\u00f3 m\u1ed9t ch\u00fat phi\u1ec1n ph\u1ee9c.`,
  `\u1eeam, kh\u00f4ng c\u00f3 phi\u1ec1n ph\u1ee9c l\u1edbn.`,
  `T\u00f4i d\u00f9ng ti\u1ec1n m\u1eb7t \u0111\u01b0\u1ee3c kh\u00f4ng?`,
  `\u1eeam, \u0111\u1ec3 t\u00f4i xem c\u00f3 ti\u1ec1n l\u1ebb kh\u00f4ng.`,
  `\u1eeam. C\u00f3 l\u1ebd c\u00f4 ph\u1ea3i \u0111\u01b0a c\u1ea3 t\u1edd m\u1edbi \u0111\u01b0\u1ee3c, v\u00ec ch\u00fang t\u00f4i kh\u00f4ng c\u00f3 ti\u1ec1n l\u1ebb \u0111\u1ec3 th\u1ed1i l\u1ea1i.`,
  `\u1eeam, v\u1eady t\u00f4i \u0111i \u0111\u1ed5i \u00edt ti\u1ec1n l\u1ebb tr\u01b0\u1edbc \u0111\u00e3.`,
  `\u0110\u1ec3 t\u00f4i \u0111i \u0111\u1ed5i \u00edt ti\u1ec1n l\u1ebb tr\u01b0\u1edbc.`,
  `Mua m\u1ed9t chai n\u01b0\u1edbc kho\u00e1ng, cu\u1ed1i c\u00f9ng c\u0169ng c\u00f3 \u00edt ti\u1ec1n l\u1ebb.`,
  `B\u00e2y gi\u1edd \u0111\u00e3 c\u00f3 \u0111\u1ee7 c\u00e1c lo\u1ea1i ti\u1ec1n l\u1ebb r\u1ed3i,`,
  `ch\u1eafc l\u00e0 c\u00f3 th\u1ec3 mua \u0111\u1ed3 \u0111\u01b0\u1ee3c r\u1ed3i.`,
  `\u1eeam. \u0110\u01b0\u1ee3c, v\u1eady t\u00f4i mu\u1ed1n m\u1ed9t ly,`,
  `t\u00f4i mu\u1ed1n tr\u00e0 s\u1eefa C\u1ed5 Minh n\u00e0y,`,
  `kh\u00f4ng \u0111\u01b0\u1eddng, th\u00eam \u0111\u1eadu \u0111\u1ecf,`,
  `v\u00e0 th\u00eam m\u1ed9t ph\u1ea7n pudding.`,
  `\u1eeam. V\u1eady ban \u0111\u1ea7u \u0111\u00e3 c\u00f3 tr\u00e2n ch\u00e2u ho\u1eb7c th\u1ea1ch d\u1eeba r\u1ed3i,`,
  `b\u1ea1n c\u00f3 c\u1ea7n th\u00eam kh\u00f4ng?`,
  `\u00c0, ch\u1ecdn tr\u00e2n ch\u00e2u, kh\u00f4ng ch\u1ecdn th\u1ea1ch d\u1eeba \u0111\u01b0\u1ee3c kh\u00f4ng?`,
  `Ch\u1ecdn tr\u00e2n ch\u00e2u. \u1eeam, \u0111\u01b0\u1ee3c.`,
  `V\u00e0 b\u1ea1n mu\u1ed1n th\u00eam m\u1ed9t ph\u1ea7n \u0111\u1eadu \u0111\u1ecf n\u1eefa,`,
  `v\u00e0 th\u00eam m\u1ed9t c\u00e1i pudding n\u1eefa \u0111\u00fang kh\u00f4ng?`,
  `\u0110\u00fang, \u0111\u00fang. \u1eeam. Ly c\u1ee1 v\u1eeba \u0111\u01b0\u1ee3c kh\u00f4ng?`,
  `\u1ed2, ly l\u1edbn v\u00e0 ly v\u1eeba gi\u00e1 t\u01b0\u01a1ng \u0111\u01b0\u01a1ng ph\u1ea3i kh\u00f4ng?`,
  `Ly l\u1edbn c\u00f3 l\u1ee3i h\u01a1n.`,
  `\u00c0, v\u1eady \u0111\u01b0\u1ee3c, v\u1eady l\u1ea5y ly l\u1edbn \u0111i.`,
  `\u1eeam, v\u00e0 kh\u00f4ng th\u00eam \u0111\u01b0\u1eddng.`,
  `13. 13. 13.`,
  `13. 13. 13.`,
  `13. 13, 13.`,
  `13. C\u00f3 c\u1ea7n \u0111\u00f3ng g\u00f3i kh\u00f4ng?`,
  `\u1ed2, kh\u00f4ng c\u1ea7n \u0111\u00f3ng g\u00f3i, u\u1ed1ng t\u1ea1i \u0111\u00e2y.`,
  `\u0110\u01b0\u1ee3c, c\u1ea3m \u01a1n. Kh\u00f4ng c\u00f3 g\u00ec.`,
  `Ban \u0111\u1ea7u t\u00f4i \u0111\u1ecbnh mua m\u1ed9t ly tr\u00e0 s\u1eefa l\u00e0nh m\u1ea1nh h\u01a1n m\u1ed9t ch\u00fat,`,
  `tr\u00e0 s\u1eefa kh\u00f4ng \u0111\u01b0\u1eddng,`,
  `nh\u01b0ng t\u00f4i \u0111\u00e3 g\u1ecdi r\u1ea5t nhi\u1ec1u topping, nh\u1eefng topping n\u00e0y \u0111\u1ec1u ng\u1ecdt,`,
  `n\u00ean n\u00f3 v\u1eabn l\u00e0 m\u1ed9t ly tr\u00e0 s\u1eefa ng\u1ecdt.`,
  `V\u1eady c\u00e1c b\u1ea1n th\u1ea5y c\u00e1i n\u00e0y l\u00e0 l\u00e0nh m\u1ea1nh hay kh\u00f4ng l\u00e0nh m\u1ea1nh?`,
  `B\u1eafc H\u1ea3i c\u00f3 nhi\u1ec1u c\u1ea3ng c\u00e1.`,
  `G\u1ea7n c\u1ea3ng c\u00e1 n\u00e0y c\u00f3 m\u1ed9t d\u00e3y ph\u1ed1 \u1ea9m th\u1ef1c.`,
  `\u1ede \u0111\u00e2y c\u00f3 \u0111\u1ee7 lo\u1ea1i \u0111\u1ed3 \u0103n v\u1eb7t v\u00e0 h\u1ea3i s\u1ea3n.`,
  `Nhi\u1ec1u ng\u01b0\u1eddi \u0111ang x\u1ebfp h\u00e0ng \u1edf \u0111\u00e2y.`,
  `H\u1ecd \u0111ang mua g\u00ec v\u1eady?`,
  `\u0110\u00e2y l\u00e0 m\u00f3n \u0103n v\u1eb7t \u0111\u1eb7c tr\u01b0ng c\u1ee7a B\u1eafc H\u1ea3i,`,
  `b\u00e1nh t\u00f4m. Nh\u01b0ng kinh nghi\u1ec7m c\u1ee7a t\u00f4i cho th\u1ea5y,`,
  `\u1edf c\u00e1c \u0111\u1ecba \u0111i\u1ec3m du l\u1ecbch,`,
  `nh\u1eefng qu\u00e1n n\u1ed5i ti\u1ebfng \u0111\u00f4ng ng\u01b0\u1eddi x\u1ebfp h\u00e0ng nh\u01b0 v\u1eady kh\u00f4ng h\u1eb3n \u0111\u00e3 ngon h\u01a1n,`,
  `n\u00ean t\u00f4i \u0111\u00e3 \u0111\u1ed5i sang m\u1ed9t qu\u00e1n \u00edt ng\u01b0\u1eddi h\u01a1n.`,
  `\u0110\u00e2y l\u00e0 khoai lang.`,
  `\u1ed2, \u0111\u00e2y l\u00e0 khoai lang chi\u00ean.`,
  `\u0110\u00e2y l\u00e0 ch\u1ea3 t\u00f4m.`,
  `\u0110\u00e2y l\u00e0 nem r\u00e1n Vi\u1ec7t Nam.`,
  `\u1ed2, ch\u1ea3 gi\u00f2 Vi\u1ec7t Nam.`,
  `C\u00e1i n\u00e0y bao nhi\u00eau ti\u1ec1n \u1ea1?`,
  `15 hai c\u00e1i. 15 hai c\u00e1i.`,
  `\u1ed2, c\u00f3 lo\u1ea1i cay v\u00e0 kh\u00f4ng cay \u0111\u00fang kh\u00f4ng?`,
  `T\u00f4i mu\u1ed1n lo\u1ea1i kh\u00f4ng cay.`,
  `Kh\u00f4ng cay. Mu\u1ed1n cay.`,
  `N\u1ebfu mu\u1ed1n cay th\u00ec \u0111\u1ec1u cho th\u00eam v\u00e0o sau.`,
  `\u1ed2, \u0111\u01b0\u1ee3c. H\u1eb9n l\u1ea7n sau nh\u00e9.`,
  `\u1ed2, \u0111\u01b0\u1ee3c, c\u1ea3m \u01a1n. Ngon kh\u00f4ng?`,
  `\u1eeam. B\u00ecnh th\u01b0\u1eddng. T\u00f4i th\u1ea5y h\u00ecnh nh\u01b0 kh\u00f4ng ngon l\u1eafm.`,
  `Nhi\u1ec1u d\u1ea7u qu\u00e1. \u1eeam, nh\u01b0ng \u0111\u00e2y l\u00e0 \u0111\u1eb7c s\u1ea3n c\u1ee7a B\u1eafc H\u1ea3i.`,
  `\u0110\u00fang. \u1eeam. \u0110\u01b0\u1ee3c r\u1ed3i, \u0111\u00e2y l\u00e0 t\u1ea5t c\u1ea3 n\u1ed9i dung c\u1ee7a h\u00f4m nay.`,
  `N\u1ebfu b\u1ea1n mu\u1ed1n t\u00ecm hi\u1ec3u v\u1ec1 \u0111\u1eb7c s\u1ea3n c\u00e1c v\u00f9ng kh\u00e1c c\u1ee7a Trung Qu\u1ed1c,`,
  `B\u1ea1n c\u00f3 th\u1ec3 xem c\u00e1c video kh\u00e1c c\u1ee7a t\u00f4i.`,
  `Hy v\u1ecdng b\u1ea1n th\u00edch,`,
  `T\u1ea1m bi\u1ec7t.`,
];

