const TEDED_GREAT_WALL_2G0HCWRL2Y8_TRANSLATIONS = [
  `M\u1ed9t con r\u1ed3ng \u0111\u1ea5t \u0111\u00e1 d\u00e0i 13.000 d\u1eb7m,`,
  `u\u1ed1n l\u01b0\u1ee3n gi\u1eefa nh\u1eefng v\u00f9ng n\u00f4ng th\u00f4n Trung Qu\u1ed1c.`,
  `L\u1ecbch s\u1eed c\u1ee7a n\u00f3 c\u0169ng l\u00e2u d\u00e0i v\u00e0 quanh co nh\u01b0 ch\u00ednh c\u1ea5u tr\u00fac c\u1ee7a n\u00f3.`,
  `V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh ban \u0111\u1ea7u l\u00e0 m\u1ed9t t\u1eadp h\u1ee3p c\u00e1c b\u1ee9c t\u01b0\u1eddng \u0111\u1ea5t n\u1ec7n,`,
  `\u0111\u01b0\u1ee3c x\u00e2y d\u1ef1ng b\u1edfi c\u00e1c qu\u1ed1c gia phong ki\u1ebfn \u0111\u1ed9c l\u1eadp trong th\u1eddi Xu\u00e2n Thu Chi\u1ebfn Qu\u1ed1c,`,
  `\u0111\u1ec3 ch\u1ed1ng l\u1ea1i nh\u1eefng k\u1ebb x\u00e2m l\u01b0\u1ee3c du m\u1ee5c t\u1eeb mi\u1ec1n b\u1eafc Trung Qu\u1ed1c v\u00e0 c\u00e1c qu\u1ed1c gia kh\u00e1c.`,
  `N\u0103m 221 tr\u01b0\u1edbc C\u00f4ng nguy\u00ean,`,
  `khi T\u1ea7n Th\u1ee7y Ho\u00e0ng th\u1ed1ng nh\u1ea5t Trung Qu\u1ed1c,`,
  `cao nguy\u00ean Thanh T\u1ea1ng v\u00e0 Th\u00e1i B\u00ecnh D\u01b0\u01a1ng tr\u1edf th\u00e0nh r\u00e0o c\u1ea3n t\u1ef1 nhi\u00ean c\u1ee7a qu\u1ed1c gia,`,
  `nh\u01b0ng c\u00e1c d\u00e3y n\u00fai ph\u00eda b\u1eafc v\u1eabn r\u1ea5t d\u1ec5 b\u1ecb ng\u01b0\u1eddi M\u00f4ng C\u1ed5,`,
  `Th\u1ed5 Nh\u0129 K\u1ef3 v\u00e0 Hung N\u00f4 x\u00e2m l\u01b0\u1ee3c.`,
  `\u0110\u1ec3 ch\u1ed1ng l\u1ea1i ngo\u1ea1i x\u00e2m,`,
  `T\u1ea7n Th\u1ee7y Ho\u00e0ng \u0111\u00e3 m\u1edf r\u1ed9ng c\u00e1c b\u1ee9c t\u01b0\u1eddng nh\u1ecf \u0111\u01b0\u1ee3c x\u00e2y d\u1ef1ng tr\u01b0\u1edbc \u0111\u00f3,`,
  `c\u1ee7ng c\u1ed1 ch\u00fang,`,
  `v\u00e0 n\u1ed1i ch\u00fang l\u1ea1i v\u1edbi nhau.`,
  `C\u1ea5u tr\u00fac t\u01b0\u1eddng th\u00e0nh b\u1eaft \u0111\u1ea7u t\u1eeb L\u00e2m Thao \u1edf ph\u00eda T\u00e2y,`,
  `K\u1ebft th\u00fac \u1edf Li\u00eau \u0110\u00f4ng ph\u00eda \u0110\u00f4ng,`,
  `C\u1ea3 hai \u0111\u01b0\u1ee3c g\u1ecdi l\u00e0 "V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh".`,
  `\u0110\u1ec3 ho\u00e0n th\u00e0nh c\u00f4ng tr\u00ecnh n\u00e0y,`,
  `T\u1ea7n Th\u1ee7y Ho\u00e0ng \u0111\u00e3 tri\u1ec7u t\u1eadp binh l\u00ednh v\u00e0 th\u01b0\u1eddng d\u00e2n,`,
  `Vi\u1ec7c n\u00e0y th\u01b0\u1eddng kh\u00f4ng d\u1ef1a tr\u00ean s\u1ef1 t\u1ef1 nguy\u1ec7n.`,
  `Trong s\u1ed1 h\u00e0ng ng\u00e0n th\u1ee3 x\u00e2y \u0111\u01b0\u1ee3c ghi nh\u1eadn d\u01b0\u1edbi th\u1eddi T\u1ea7n,`,
  `Nhi\u1ec1u ng\u01b0\u1eddi l\u00e0 n\u00f4ng d\u00e2n b\u1ecb c\u01b0\u1ee1ng b\u1ee9c lao \u0111\u1ed9ng,`,
  `M\u1ed9t s\u1ed1 kh\u00e1c l\u00e0 t\u00f9 nh\u00e2n \u0111ang trong th\u1eddi gian ch\u1ea5p h\u00e0nh \u00e1n.`,
  `V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh ti\u1ebfp t\u1ee5c \u0111\u01b0\u1ee3c m\u1edf r\u1ed9ng d\u01b0\u1edbi th\u1eddi nh\u00e0 H\u00e1n,`,
  `K\u00e9o d\u00e0i 3700 d\u1eb7m,`,
  `T\u1eeb \u0110\u00f4n Ho\u00e0ng \u0111\u1ebfn B\u1ed9t H\u1ea3i.`,
  `Lao \u0111\u1ed9ng c\u01b0\u1ee1ng b\u1ee9c ti\u1ebfp t\u1ee5c d\u01b0\u1edbi th\u1eddi H\u00e1n V\u0169 \u0110\u1ebf,`,
  `Do \u0111\u00f3, b\u1ee9c t\u01b0\u1eddng th\u00e0nh n\u1ed5i ti\u1ebfng l\u00e0 n\u01a1i ch\u1ecbu \u0111\u1ef1ng \u0111au kh\u1ed5.`,
  `Th\u01a1 ca v\u00e0 truy\u1ec1n thuy\u1ebft th\u1eddi k\u1ef3 \u0111\u00f3 m\u00f4 t\u1ea3 nh\u1eefng ng\u01b0\u1eddi lao \u0111\u1ed9ng b\u1ecb ch\u00f4n v\u00f9i trong nh\u1eefng ng\u00f4i m\u1ed9 t\u1eadp th\u1ec3 g\u1ea7n \u0111\u00f3,`,
  `Th\u1eadm ch\u00ed c\u1ea3 b\u00ean trong Tr\u01b0\u1eddng Th\u00e0nh.`,
  `Tuy nhi\u00ean, b\u00ean trong t\u01b0\u1eddng th\u00e0nh kh\u00f4ng t\u00ecm th\u1ea5y m\u1ed9 t\u1eadp th\u1ec3 ch\u1ee9a h\u00e0i c\u1ed1t ng\u01b0\u1eddi,`,
  `\u0110i\u1ec1u n\u00e0y cho th\u1ea5y h\u1ea7u h\u1ebft nh\u1eefng ng\u01b0\u1eddi lao \u0111\u1ed9ng \u0111\u00e3 ch\u1ebft v\u00ec tai n\u1ea1n,`,
  `\u0110\u00f3i kh\u00e1t v\u00e0 ki\u1ec7t s\u1ee9c.`,
  `V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh th\u1eadt \u0111\u00e1ng s\u1ee3,`,
  `Nh\u01b0ng kh\u00f4ng ph\u1ea3i l\u00e0 kh\u00f4ng th\u1ec3 v\u01b0\u1ee3t qua.`,
  `Th\u00e0nh C\u00e1t T\u01b0 H\u00e3n v\u00e0 con trai H\u1ed1t T\u1ea5t Li\u1ec7t \u0111\u00e3 v\u01b0\u1ee3t qua \u0111\u01b0\u1ee3c b\u1ee9c t\u01b0\u1eddng th\u00e0nh khi M\u00f4ng C\u1ed5 x\u00e2m l\u01b0\u1ee3c v\u00e0o th\u1ebf k\u1ef7 13.`,
  `Sau khi nh\u00e0 Minh l\u00ean n\u1eafm quy\u1ec1n v\u00e0o n\u0103m 1368,`,
  `H\u1ecd b\u1eaft \u0111\u1ea7u s\u1eed d\u1ee5ng g\u1ea1ch v\u00e0 \u0111\u00e1 nung t\u1eeb c\u00e1c l\u00f2 \u0111\u1ecba ph\u01b0\u01a1ng,`,
  `\u0110\u1ec3 c\u1ee7ng c\u1ed1 v\u00e0 gia c\u1ed1 l\u1ea1i V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh.`,
  `Tr\u01b0\u1eddng Th\u00e0nh c\u00f3 chi\u1ec1u cao trung b\u00ecnh 7 m\u00e9t,`,
  `R\u1ed9ng 6 m\u00e9t. D\u1ecdc theo b\u1ee9c t\u01b0\u1eddng th\u00e0nh d\u00e0i 5500 d\u1eb7m c\u00f3 c\u00e1c th\u00e1p canh,`,
  `M\u1ed9t khi ph\u00e1t hi\u1ec7n qu\u00e2n x\u00e2m l\u01b0\u1ee3c, c\u00e1c th\u00e1p canh s\u1ebd truy\u1ec1n t\u00edn hi\u1ec7u b\u1eb1ng kh\u00f3i v\u00e0 l\u1eeda`,
  `Cho \u0111\u1ebfn khi qu\u00e2n ti\u1ebfp vi\u1ec7n \u0111\u1ebfn.`,
  `C\u00e1c l\u1ed7 nh\u1ecf tr\u00ean t\u01b0\u1eddng th\u00e0nh cho ph\u00e9p cung th\u1ee7 b\u1eafn xuy\u00ean qua nh\u1eefng k\u1ebb x\u00e2m l\u01b0\u1ee3c,`,
  `L\u1ed7 l\u1edbn d\u00f9ng \u0111\u1ec3 n\u00e9m \u0111\u00e1 ho\u1eb7c c\u00e1c v\u1eadt kh\u00e1c.`,
  `Nh\u01b0ng ngay c\u1ea3 b\u1ee9c t\u01b0\u1eddng th\u00e0nh c\u1ea3i ti\u1ebfn n\u00e0y v\u1eabn ch\u01b0a \u0111\u1ee7 t\u1ed1t.`,
  `N\u0103m 1644,`,
  `ng\u01b0\u1eddi M\u00e3n Ch\u00e2u t\u1eeb ph\u00eda b\u1eafc l\u1eadt \u0111\u1ed5 nh\u00e0 Minh,`,
  `th\u00e0nh l\u1eadp nh\u00e0 Thanh,`,
  `\u0111\u1ed3ng th\u1eddi s\u00e1p nh\u1eadp M\u00f4ng C\u1ed5.`,
  `Do \u0111\u00f3, \u0111\u00e2y l\u00e0 l\u1ea7n th\u1ee9 hai Trung Qu\u1ed1c b\u1ecb cai tr\u1ecb b\u1edfi ngo\u1ea1i bang m\u00e0 h\u1ecd t\u1eebng mu\u1ed1n \u0111\u1ea9y l\u00f9i b\u1eb1ng V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh.`,
  `Khi bi\u00ean gi\u1edbi \u0111\u1ebf ch\u1ebf m\u1edf r\u1ed9ng ra ngo\u00e0i V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh,`,
  `Nh\u1eefng c\u00f4ng s\u1ef1 n\u00e0y m\u1ea5t \u0111i m\u1ee5c \u0111\u00edch ban \u0111\u1ea7u,`,
  `Kh\u00f4ng \u0111\u01b0\u1ee3c gia c\u1ed1 \u0111\u1ecbnh k\u1ef3,`,
  `T\u01b0\u1eddng th\u00e0nh h\u01b0 h\u1ecfng n\u1eb7ng,`,
  `\u0110\u1ea5t n\u1ec7n b\u1ecb x\u00f3i m\u00f2n,`,
  `G\u1ea1ch v\u00e0 \u0111\u00e1 b\u1ecb \u0111\u00e1nh c\u1eafp l\u00e0m v\u1eadt li\u1ec7u x\u00e2y d\u1ef1ng,`,
  `Nh\u01b0ng s\u1ee9 m\u1ec7nh c\u1ee7a V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh v\u1eabn ch\u01b0a k\u1ebft th\u00fac.`,
  `Trong Th\u1ebf chi\u1ebfn th\u1ee9 hai,`,
  `Trung Qu\u1ed1c s\u1eed d\u1ee5ng m\u1ed9t ph\u1ea7n V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh \u0111\u1ec3 ch\u1ed1ng l\u1ea1i s\u1ef1 x\u00e2m l\u01b0\u1ee3c c\u1ee7a Nh\u1eadt B\u1ea3n,`,
  `m\u1ed9t ph\u1ea7n c\u1ee7a V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh v\u1eabn \u0111\u01b0\u1ee3c \u0111\u1ed3n \u0111\u1ea1i l\u00e0 \u0111\u01b0\u1ee3c s\u1eed d\u1ee5ng cho hu\u1ea5n luy\u1ec7n qu\u00e2n s\u1ef1.`,
  `Tuy nhi\u00ean, ng\u00e0y nay v\u0103n h\u00f3a m\u1edbi l\u00e0 m\u1ee5c \u0111\u00edch ch\u00ednh c\u1ee7a V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh.`,
  `L\u00e0 m\u1ed9t trong nh\u1eefng c\u00f4ng tr\u00ecnh nh\u00e2n t\u1ea1o l\u1edbn nh\u1ea5t tr\u00ean Tr\u00e1i \u0110\u1ea5t,`,
  `V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh \u0111\u00e3 \u0111\u01b0\u1ee3c UNESCO c\u00f4ng nh\u1eadn l\u00e0 Di s\u1ea3n Th\u1ebf gi\u1edbi v\u00e0o n\u0103m 1987.`,
  `V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh ban \u0111\u1ea7u \u0111\u01b0\u1ee3c x\u00e2y d\u1ef1ng \u0111\u1ec3 ph\u00f2ng th\u1ee7, ng\u0103n ch\u1eb7n ng\u01b0\u1eddi ngo\u00e0i x\u00e2m nh\u1eadp Trung Qu\u1ed1c,`,
  `nh\u01b0ng ng\u00e0y nay \u0111\u00f3n h\u00e0ng tri\u1ec7u du kh\u00e1ch m\u1ed7i n\u0103m.`,
  `Th\u1ef1c t\u1ebf, l\u01b0\u1ee3ng l\u1edbn du kh\u00e1ch \u0111\u00e3 khi\u1ebfn V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh ng\u00e0y c\u00e0ng h\u01b0 h\u1ea1i,`,
  `bu\u1ed9c ch\u00ednh ph\u1ee7 Trung Qu\u1ed1c ph\u1ea3i kh\u1edfi \u0111\u1ed9ng c\u00e1c bi\u1ec7n ph\u00e1p b\u1ea3o v\u1ec7.`,
  `N\u00f3 c\u0169ng th\u01b0\u1eddng \u0111\u01b0\u1ee3c tuy\u00ean b\u1ed1 l\u00e0 c\u00f4ng tr\u00ecnh nh\u00e2n t\u1ea1o duy nh\u1ea5t c\u00f3 th\u1ec3 nh\u00ecn th\u1ea5y t\u1eeb kh\u00f4ng gian.`,
  `Kh\u00f4ng may, tuy\u00ean b\u1ed1 n\u00e0y kh\u00f4ng ho\u00e0n to\u00e0n ch\u00ednh x\u00e1c.`,
  `T\u1eeb qu\u1ef9 \u0111\u1ea1o Tr\u00e1i \u0110\u1ea5t, nhi\u1ec1u c\u00f4ng tr\u00ecnh kh\u00e1c nhau nh\u01b0 c\u1ea7u,`,
  `\u0111\u01b0\u1eddng cao t\u1ed1c v\u00e0 s\u00e2n bay \u0111\u1ec1u c\u00f3 th\u1ec3 nh\u00ecn th\u1ea5y,`,
  `trong khi V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh l\u1ea1i m\u1edd \u1ea3o,`,
  `v\u00e0 ho\u00e0n to\u00e0n kh\u00f4ng th\u1ec3 nh\u00ecn th\u1ea5y t\u1eeb M\u1eb7t Tr\u0103ng.`,
  `Nh\u01b0ng d\u00f9 th\u1ebf n\u00e0o \u0111i n\u1eefa,`,
  `Tr\u00e1i \u0111\u1ea5t m\u1edbi l\u00e0 n\u01a1i ch\u00fang ta n\u00ean nghi\u00ean c\u1ee9u k\u1ef9 V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh,`,
  `v\u00ec c\u1ee9 v\u00e0i n\u0103m l\u1ea1i c\u00f3 nh\u1eefng \u0111o\u1ea1n m\u1edbi \u0111\u01b0\u1ee3c ph\u00e1t hi\u1ec7n,`,
  `ch\u00fang m\u1edf r\u1ed9ng t\u1eeb ph\u1ea7n ch\u00ednh,`,
  `kh\u00f4ng ng\u1eebng k\u00e9o d\u00e0i k\u1ef3 t\u00edch v\u0129 \u0111\u1ea1i n\u00e0y, m\u1ed9t minh ch\u1ee9ng cho th\u00e0nh t\u1ef1u c\u1ee7a nh\u00e2n lo\u1ea1i.`,
  `Cung ho\u00e0ng \u0111\u1ea1o c\u1ee7a b\u1ea1n l\u00e0 g\u00ec?`,
  `Trong 12 con gi\u00e1p Trung Qu\u1ed1c,`,
  `n\u0103m sinh t\u01b0\u01a1ng \u1ee9ng v\u1edbi m\u1ed9t con v\u1eadt,`,
  `t\u1ea5t c\u1ea3 \u0111\u1ec1u b\u1eaft ngu\u1ed3n t\u1eeb m\u1ed9t cu\u1ed9c thi l\u1edbn.`,
  `H\u00e3y xem video n\u00e0y,`,
  `\u0111\u1ec3 hi\u1ec3u s\u00e2u h\u01a1n v\u1ec1 ngu\u1ed3n g\u1ed1c c\u1ee7a 12 con gi\u00e1p Trung Qu\u1ed1c.`,
];

