const TEDED_VALUE_PARADOX_F8XB3W31XCW_TRANSLATIONS = [
  `Gi\u1ea3 s\u1eed trong m\u1ed9t ch\u01b0\u01a1ng tr\u00ecnh \u0111\u1ed1 vui c\u00f3 th\u01b0\u1edfng,`,
  `B\u1ea1n c\u00f3 hai gi\u1ea3i th\u01b0\u1edfng \u0111\u1ec3 ch\u1ecdn:`,
  `M\u1ed9t vi\u00ean kim c\u01b0\u01a1ng v\u00e0 m\u1ed9t chai n\u01b0\u1edbc.`,
  `Vi\u1ec7c l\u1ef1a ch\u1ecdn gi\u1eefa ch\u00fang r\u1ea5t d\u1ec5 d\u00e0ng,`,
  `R\u00f5 r\u00e0ng gi\u00e1 tr\u1ecb c\u1ee7a kim c\u01b0\u01a1ng cao h\u01a1n n\u01b0\u1edbc.`,
  `B\u00e2y gi\u1edd h\u00e3y h\u00ecnh dung b\u1ea1n \u0111\u1ed1i m\u1eb7t v\u1edbi l\u1ef1a ch\u1ecdn t\u01b0\u01a1ng t\u1ef1,`,
  `Nh\u01b0ng l\u1ea7n n\u00e0y b\u1ea1n kh\u00f4ng \u1edf trong m\u1ed9t ch\u01b0\u01a1ng tr\u00ecnh \u0111\u1ed1 vui c\u00f3 th\u01b0\u1edfng,`,
  `M\u00e0 l\u00e0 \u0111ang \u0111i xuy\u00ean qua sa m\u1ea1c nhi\u1ec1u ng\u00e0y v\u00e0 c\u01a1 th\u1ec3 thi\u1ebfu n\u01b0\u1edbc tr\u1ea7m tr\u1ecdng.`,
  `S\u1ef1 l\u1ef1a ch\u1ecdn c\u1ee7a b\u1ea1n c\u00f3 kh\u00e1c kh\u00f4ng?`,
  `T\u1ea1i sao? Ch\u1eb3ng l\u1ebd gi\u00e1 tr\u1ecb c\u1ee7a kim c\u01b0\u01a1ng v\u1eabn kh\u00f4ng cao h\u01a1n n\u01b0\u1edbc sao?`,
  `\u0110\u00e2y ch\u00ednh l\u00e0`,
  `\u0110\u01b0\u1ee3c \u0111\u1ec1 xu\u1ea5t l\u1ea7n \u0111\u1ea7u b\u1edfi Adam Smith, nh\u00e0 ti\u00ean phong kinh t\u1ebf h\u1ecdc.`,
  `\u00d4ng \u1ea5y n\u00f3i v\u1edbi ch\u00fang ta r\u1eb1ng,`,
  `Vi\u1ec7c x\u00e1c \u0111\u1ecbnh gi\u00e1 tr\u1ecb th\u1ef1c ra kh\u00f4ng \u0111\u01a1n gi\u1ea3n nh\u01b0 v\u1ebb ngo\u00e0i c\u1ee7a n\u00f3.`,
  `Trong ch\u01b0\u01a1ng tr\u00ecnh \u0111\u1ed1 vui c\u00f3 th\u01b0\u1edfng, b\u1ea1n \u0111ang xem x\u00e9t gi\u00e1 tr\u1ecb trao \u0111\u1ed5i c\u1ee7a m\u00f3n \u0111\u1ed3,`,
  `\u0110\u00f3 ch\u00ednh l\u00e0 gi\u00e1 tr\u1ecb b\u1ea1n c\u00f3 th\u1ec3 nh\u1eadn \u0111\u01b0\u1ee3c t\u1eeb n\u00f3 sau n\u00e0y.`,
  `Nh\u01b0ng trong c\u00e1c t\u00ecnh hu\u1ed1ng kh\u1ea9n c\u1ea5p,`,
  `v\u00ed d\u1ee5 nh\u01b0 c\u1ea3nh sa m\u1ea1c \u0111\u00e3 \u0111\u1ec1 c\u1eadp tr\u01b0\u1edbc \u0111\u00f3,`,
  `gi\u00e1 tr\u1ecb s\u1eed d\u1ee5ng c\u1ee7a v\u1eadt ph\u1ea9m tr\u1edf n\u00ean quan tr\u1ecdng h\u01a1n,`,
  `t\u1ee9c l\u00e0 v\u1eadt ph\u1ea9m \u0111\u00f3 c\u00f3 th\u1ec3 gi\u00fap \u00edch cho b\u1ea1n \u0111\u1ebfn m\u1ee9c n\u00e0o trong ho\u00e0n c\u1ea3nh hi\u1ec7n t\u1ea1i.`,
  `V\u00ec ch\u1ec9 c\u00f3 th\u1ec3 ch\u1ecdn m\u1ed9t trong s\u1ed1 \u0111\u00f3,`,
  `n\u00ean ch\u00fang ta c\u0169ng ph\u1ea3i xem x\u00e9t chi ph\u00ed c\u01a1 h\u1ed9i,`,
  `t\u1ee9c l\u00e0 n\u1ebfu t\u1eeb b\u1ecf c\u00e1c l\u1ef1a ch\u1ecdn kh\u00e1c,`,
  `ch\u00fang ta s\u1ebd m\u1ea5t g\u00ec.`,
  `X\u00e9t cho c\u00f9ng, n\u1ebfu b\u1ea1n kh\u00f4ng th\u1ec3 tho\u00e1t kh\u1ecfi sa m\u1ea1c,`,
  `th\u00ec vi\u1ec7c vi\u00ean kim c\u01b0\u01a1ng b\u00e1n \u0111\u01b0\u1ee3c bao nhi\u00eau ti\u1ec1n c\u0169ng kh\u00f4ng quan tr\u1ecdng.`,
  `Khi n\u00f3i v\u1ec1 ngh\u1ecbch l\u00fd gi\u00e1 tr\u1ecb,`,
  `h\u1ea7u h\u1ebft c\u00e1c nh\u00e0 kinh t\u1ebf hi\u1ec7n \u0111\u1ea1i s\u1ebd t\u00edch h\u1ee3p c\u00e1c y\u1ebfu t\u1ed1 c\u00e2n nh\u1eafc n\u00e0y v\u00e0o kh\u00e1i ni\u1ec7m "ti\u1ec7n \u00edch\u201d,`,
  `ngh\u0129a l\u00e0 m\u1ee9c \u0111\u1ed9 v\u1eadt ph\u1ea9m th\u1ecfa m\u00e3n mong mu\u1ed1n ho\u1eb7c nhu c\u1ea7u c\u00e1 nh\u00e2n.`,
  `T\u1eeb nhu c\u1ea7u c\u01a1 b\u1ea3n v\u1ec1 th\u1ee9c \u0103n cho \u0111\u1ebfn c\u1ea3m gi\u00e1c vui v\u1ebb khi nghe nh\u1ea1c y\u00eau th\u00edch,`,
  `Hi\u1ec7u d\u1ee5ng c\u00f3 th\u1ec3 \u0111\u01b0\u1ee3c \u00e1p d\u1ee5ng cho b\u1ea5t c\u1ee9 th\u1ee9 g\u00ec,`,
  `t\u1ef1 nhi\u00ean c\u0169ng kh\u00e1c nhau t\u00f9y ng\u01b0\u1eddi, t\u00f9y c\u1ea3nh.`,
  `Kinh t\u1ebf th\u1ecb tr\u01b0\u1eddng cung c\u1ea5p cho ch\u00fang ta m\u1ed9t c\u00e1ch \u0111\u01a1n gi\u1ea3n \u0111\u1ec3 "theo d\u00f5i hi\u1ec7u d\u1ee5ng",`,
  `n\u00f3i \u0111\u01a1n gi\u1ea3n, hi\u1ec7u d\u1ee5ng c\u1ee7a m\u1ed9t m\u00f3n \u0111\u1ed3 c\u00f3 th\u1ec3 \u0111\u01b0\u1ee3c ph\u1ea3n \u00e1nh qua gi\u00e1 tr\u1ecb b\u1ea1n s\u1eb5n l\u00f2ng chi tr\u1ea3 cho n\u00f3.`,
  `B\u00e2y gi\u1edd gi\u1ea3 s\u1eed b\u1ea1n tr\u1edf l\u1ea1i sa m\u1ea1c,`,
  `nh\u01b0ng l\u1ea7n n\u00e0y c\u1ee9 sau 5 ph\u00fat b\u1ea1n s\u1ebd nh\u1eadn \u0111\u01b0\u1ee3c m\u1ed9t vi\u00ean kim c\u01b0\u01a1ng m\u1edbi ho\u1eb7c m\u1ed9t chai n\u01b0\u1edbc m\u1edbi.`,
  `N\u1ebfu b\u1ea1n gi\u1ed1ng nh\u01b0 h\u1ea7u h\u1ebft m\u1ecdi ng\u01b0\u1eddi,`,
  `b\u1ea1n s\u1ebd ch\u1ecdn \u0111\u1ee7 n\u01b0\u1edbc d\u00f9ng cho to\u00e0n b\u1ed9 h\u00e0nh tr\u00ecnh tr\u01b0\u1edbc,`,
  `sau \u0111\u00f3 ch\u1ecdn c\u00e0ng nhi\u1ec1u kim c\u01b0\u01a1ng c\u00e0ng t\u1ed1t.`,
  `\u0110\u00e2y l\u00e0 v\u00ec c\u00f3 hi\u1ec7u d\u1ee5ng bi\u00ean,`,
  `t\u1ee9c l\u00e0 khi c\u00e2n nh\u1eafc kim c\u01b0\u01a1ng v\u00e0 n\u01b0\u1edbc,`,
  `b\u1ea1n s\u1ebd so s\u00e1nh hi\u1ec7u d\u1ee5ng c\u1ee7a m\u1ed7i chai n\u01b0\u1edbc th\u00eam v\u00e0 m\u1ed7i vi\u00ean kim c\u01b0\u01a1ng th\u00eam.`,
  `M\u1ed7i l\u1ea7n nh\u1eadn \u0111\u01b0\u1ee3c n\u01b0\u1edbc v\u00e0 kim c\u01b0\u01a1ng, b\u1ea1n s\u1ebd so s\u00e1nh nh\u01b0 v\u1eady:`,
  `Chai n\u01b0\u1edbc \u0111\u1ea7u ti\u00ean \u0111\u1ed1i v\u1edbi b\u1ea1n c\u00f3 gi\u00e1 tr\u1ecb ng\u00e0n v\u00e0ng kh\u00f3 \u0111\u1ed5i,`,
  `nh\u01b0ng cu\u1ed1i c\u00f9ng b\u1ea1n s\u1ebd c\u00f3 \u0111\u1ee7 n\u01b0\u1edbc.`,
  `M\u1ed9t th\u1eddi gian sau, m\u1ed7i chai n\u01b0\u1edbc d\u01b0 th\u1eeba tr\u1edf th\u00e0nh g\u00e1nh n\u1eb7ng.`,
  `L\u00fac n\u00e0y, b\u1ea1n b\u1eaft \u0111\u1ea7u ch\u1ecdn kim c\u01b0\u01a1ng thay v\u00ec n\u01b0\u1edbc.`,
  `\u0110i\u1ec1u n\u00e0y kh\u00f4ng ch\u1ec9 \u00e1p d\u1ee5ng cho nh\u1eefng nhu y\u1ebfu ph\u1ea9m nh\u01b0 n\u01b0\u1edbc,`,
  `m\u00e0 c\u00f2n \u0111\u00fang v\u1edbi h\u1ea7u h\u1ebft c\u00e1c m\u1eb7t h\u00e0ng.`,
  `B\u1ea1n c\u00e0ng nh\u1eadn \u0111\u01b0\u1ee3c nhi\u1ec1u,`,
  `t\u1ef7 l\u1ec7 th\u1ecfa m\u00e3n ho\u1eb7c l\u1ee3i \u00edch thu \u0111\u01b0\u1ee3c tr\u00ean m\u1ed7i \u0111\u01a1n v\u1ecb t\u0103ng th\u00eam s\u1ebd gi\u1ea3m d\u1ea7n.`,
  `\u0110\u00e2y ch\u00ednh l\u00e0 quy lu\u1eadt l\u1ee3i \u00edch c\u1eadn bi\u00ean gi\u1ea3m d\u1ea7n.`,
  `Mua hai ho\u1eb7c ba ph\u1ea7n m\u00f3n \u0103n y\u00eau th\u00edch,`,
  `c\u00f3 th\u1ec3 b\u1ea1n s\u1ebd r\u1ea5t vui;`,
  `\u0111\u1ebfn ph\u1ea7n th\u1ee9 t\u01b0 b\u1ea1n s\u1ebd b\u1eaft \u0111\u1ea7u th\u1ea5y ch\u00e1n gh\u00e9t;`,
  `\u0111\u1ebfn ph\u1ea7n th\u1ee9 100 c\u00f3 th\u1ec3 b\u1ea1n s\u1ebd kh\u00f4ng bao gi\u1edd mu\u1ed1n \u0103n n\u1eefa;`,
  `ho\u1eb7c b\u1ea1n c\u00f3 th\u1ec3 b\u1ecf ti\u1ec1n \u0111i xem c\u00f9ng m\u1ed9t b\u1ed9 phim,`,
  `cho \u0111\u1ebfn khi ch\u00e1n ho\u1eb7c h\u1ebft s\u1ea1ch ti\u1ec1n.`,
  `D\u00f9 l\u00e0 tr\u01b0\u1eddng h\u1ee3p n\u00e0o,`,
  `cu\u1ed1i c\u00f9ng b\u1ea1n s\u1ebd \u0111\u1ea1t \u0111\u1ebfn \u0111i\u1ec3m m\u00e0 l\u1ee3i \u00edch c\u1eadn bi\u00ean c\u1ee7a vi\u1ec7c mua th\u00eam m\u1ed9t v\u00e9 xem phim b\u1eb1ng 0.`,
  `L\u1ee3i \u00edch kh\u00f4ng ch\u1ec9 \u00e1p d\u1ee5ng khi mua s\u1eafm m\u00e0 c\u00f2n cho m\u1ecdi quy\u1ebft \u0111\u1ecbnh c\u1ee7a ch\u00fang ta.`,
  `C\u00f3 m\u1ed9t c\u00e1ch \u0111\u01a1n gi\u1ea3n \u0111\u1ec3 t\u1ed1i \u0111a h\u00f3a l\u1ee3i \u00edch v\u00e0 tr\u00e1nh quy lu\u1eadt l\u1ee3i \u00edch c\u1eadn bi\u00ean gi\u1ea3m d\u1ea7n,`,
  `\u0111\u00f3 l\u00e0 kh\u00f4ng ng\u1eebng thay \u0111\u1ed5i c\u00e1ch ch\u00fang ta s\u1eed d\u1ee5ng th\u1eddi gian v\u00e0 t\u00e0i nguy\u00ean.`,
  `Sau khi \u0111\u00e1p \u1ee9ng c\u00e1c nhu c\u1ea7u c\u01a1 b\u1ea3n,`,
  `v\u1ec1 l\u00fd thuy\u1ebft, ch\u00fang ta s\u1ebd quy\u1ebft \u0111\u1ecbnh ch\u1ec9 \u0111\u1ea7u t\u01b0 v\u00e0o s\u1ed1 l\u01b0\u1ee3ng h\u00e0ng h\u00f3a mang l\u1ea1i l\u1ee3i \u00edch ho\u1eb7c ni\u1ec1m vui cho m\u00ecnh.`,
  `T\u1ea5t nhi\u00ean, vi\u1ec7c m\u1ed7i ch\u00fang ta t\u1ed1i \u0111a h\u00f3a l\u1ee3i \u00edch hi\u1ec7u qu\u1ea3 nh\u01b0 th\u1ebf n\u00e0o trong cu\u1ed9c s\u1ed1ng th\u1ef1c l\u1ea1i l\u00e0 m\u1ed9t v\u1ea5n \u0111\u1ec1 kh\u00e1c,`,
  `nh\u01b0ng \u0111i\u1ec1u quan tr\u1ecdng c\u1ea7n nh\u1edb l\u00e0,`,
  `ngu\u1ed3n g\u1ed1c cu\u1ed1i c\u00f9ng c\u1ee7a gi\u00e1 tr\u1ecb l\u00e0 ch\u00fang ta,`,
  `nh\u1eefng nhu c\u1ea7u chung c\u1ee7a ch\u00fang ta, nh\u1eefng g\u00ec ch\u00fang ta y\u00eau th\u00edch v\u00e0 nh\u1eefng l\u1ef1a ch\u1ecdn c\u1ee7a ch\u00fang ta.`,
  `B\u1ea1n \u0111\u00e3 s\u1eb5n s\u00e0ng ti\u1ebfp t\u1ee5c h\u1ecdc h\u1ecfi ch\u01b0a?`,
  `Xem c\u00e1c video n\u00e0y \u0111\u1ec3 th\u1eed th\u00e1ch nh\u1eadn th\u1ee9c c\u1ee7a b\u1ea1n,`,
  `ho\u1eb7c n\u1eafm v\u1eefng ki\u1ebfn th\u1ee9c m\u00e0 b\u1ea1n ch\u01b0a bi\u1ebft,`,
  `\u0111\u0103ng k\u00fd v\u00e0 lu\u00f4n t\u00f2 m\u00f2.`,
];

